            continue

        if k in ('languages', 'translated_from'):
            formatted_languages = format_languages(languages=v)
            book[k] = formatted_languages
            continue

        if k in type_map:
            t = '/type/' + type_map[k]
            if isinstance(v, list):
                book[k] = [{'type': t, 'value': i} for i in v]
            else:
                book[k] = {'type': t, 'value': v}
        else:
            book[k] = v
    return book

